    return Schema.decodeUnknownOption(RepoFlow.RunRequest)(intent.payload).pipe(Option.filter((request) => request.run === intent.executionId), Option.map((request) => ({ execution: request.run, repoId: `github/${request.repo.toLowerCase()}` })));
